function A({registerIndicator:Y,nulls:k}){Y({id:"oa-yzv",name:"Yang-Zhang Volatility (YZV)",category:"Volatility",placement:"pane",inputs:[{key:"length",type:"number",label:"Length",default:20,min:1,max:5e3,step:1,tooltip:"The lookback period for smoothing Yang-Zhang daily variance estimates."}],plots:[{key:"yzv",type:"line",title:"YZV",style:{color:"#ffeb3b",lineWidth:2}}],calc(c,q){const o=Math.max(1,Math.floor(Number(q.length)||20)),r=c.length,h=new Array(r).fill(NaN),m=.34/(1.34+(o<=1?1:(o+1)/(o-1))),z=1/o,V=1e-10;let n=0,s=1;for(let t=0;t<r;t++){const l=c[t],e=Number(l.open),u=Number(l.high),N=Number(l.low),g=Number(l.close),p=t>0?Number(c[t-1].close):NaN,y=Number.isFinite(p)?p:e;if(!(e>0)||!(u>0)||!(N>0)||!(g>0)||!(y>0))continue;const b=Math.log(e/y),a=Math.log(g/e),f=Math.log(u/e),d=Math.log(N/e),Z=b*b,w=a*a,x=f*(f-a)+d*(d-a),i=Z+m*w+(1-m)*x;if(!Number.isFinite(i))continue;t===0?n=i:n=(n*(o-1)+i)/o,s=(1-z)*s;const M=1-s,v=s>V&&M!==0?n/M:n;h[t]=v>=0?Math.sqrt(v):NaN}return{yzv:k(h)}}})}export{A as default};
